window.TAX_ATLAS_RECORDS=[{"id":"gb-window","country":"GB","title":"Pencere Vergisi","period":"1696–1851","year":1696,"status":"gecmis","group":"Ev","motifs":["pencere","konut","kaçınma"],"teaser":"Evin dışarıya baktığı her açıklığın bir bedeli vardı.","story":"İngiltere’de pencere sayısı, vergi değerlendirmesinde kullanıldı. Bazı ev sahiplerinin pencereleri tuğlayla kapatması bu verginin en kalıcı görsel izlerinden biri.","url":"https://www.nationalarchives.gov.uk/education/resources/georgian-britain-age-modernity/window-tax/","source":"The National Archives"},{"id":"gb-hearth","country":"GB","title":"Şömine Vergisi","period":"1662–1689","year":1662,"status":"gecmis","group":"Ev","motifs":["konut","ısınma","sayım"],"teaser":"Bacalar sadece duman değil, vergi de çıkarıyordu.","story":"İngiltere’de evdeki ocak ve şömine sayısı üzerinden vergi alınması, serveti ev içindeki görünür eşyalardan hesaplama çabasıydı.","url":"https://www.bdmuseum.nl/en/exhibitions/bizarre-belastingen/","source":"Vergi ve Gümrük Müzesi"},{"id":"gb-brick","country":"GB","title":"Tuğla Vergisi","period":"1784–1850","year":1784,"status":"gecmis","group":"Ev","motifs":["konut","kaçınma","üretim"],"teaser":"Tuğlayı vergilendirince tuğlalar büyüdü.","story":"Britanya’da adet başına vergi, üreticileri daha büyük tuğla yapmaya teşvik etti. 1803’te aşırı büyük tuğlalar için tarife sıkılaştırıldı.","url":"https://www.scottishbrickhistory.co.uk/brick-tax-1784-1850/","source":"Scottish Brick History"},{"id":"gb-wallpaper","country":"GB","title":"Duvar Kâğıdı Vergisi","period":"1712–1836","year":1712,"status":"gecmis","group":"Ev","motifs":["konut","kaçınma","dekorasyon"],"teaser":"Duvarını süslemek de maliyenin konusu oldu.","story":"Baskılı ve boyalı duvar kâğıtları vergilendirilince bazı üreticiler önce düz kâğıt asıp desenlemeyi sonradan yaparak vergiden kaçınmaya çalıştı.","url":"https://www.vam.ac.uk/articles/a-brief-history-of-wallpaper","source":"Victoria and Albert Museum"},{"id":"gb-hat","country":"GB","title":"Şapka Vergisi","period":"1784–1811","year":1784,"status":"gecmis","group":"Giyim","motifs":["moda","belge","damga"],"teaser":"Şapkana devlet pulu yapıştırman gerekiyordu.","story":"Britanya’da erkek şapkalarının satışı üzerinde, özel damga kullanılarak takip edilen bir vergi vardı. Şapka alımının bir tür varlık göstergesi olduğu varsayılıyordu.","url":"https://now.fordham.edu/politics-and-society/historys-weirdest-taxes/","source":"Fordham University"},{"id":"gb-powder","country":"GB","title":"Saç Pudrası Vergisi","period":"1795–1869","year":1795,"status":"gecmis","group":"Giyim","motifs":["moda","belge","kaçınma"],"teaser":"Beyaz pudralı saç için yıllık izin.","story":"1795’te Britanya’da saç pudrası kullanımı yıllık bir sertifikaya bağlandı. Moda ve vergi politikası aynı dönemde değişti.","url":"https://www.parliament.uk/about/living-heritage/transformingsociety/private-lives/taxation/overview/taxes18thcentury/","source":"UK Parliament"},{"id":"gb-soap","country":"GB","title":"Sabun Vergisi","period":"1712–1853","year":1712,"status":"gecmis","group":"Gündelik","motifs":["hijyen","üretim","kaçınma"],"teaser":"Temizlenmenin de ayrı hesabı vardı.","story":"Britanya’da sabun üretimi vergiye tabi tutuldu ve bu vergi 1853’te kaldırıldı. Bir zorunlu tüketim malı mali gelir kaynağıydı.","url":"https://now.fordham.edu/politics-and-society/historys-weirdest-taxes/","source":"Fordham University"},{"id":"gb-cards","country":"GB","title":"Oyun Kâğıdı Damgası","period":"16. yy–1960","year":1600,"status":"gecmis","group":"Gündelik","motifs":["oyun","damga","eğlence"],"teaser":"Asın üzerindeki süs bir zamanlar makbuzdu.","story":"Britanya’da oyun kâğıtları vergi damgalarıyla takip edildi. Maça asının gösterişli tasarımı bu geleneğin izlerini taşıyor.","url":"https://barnesroffe.com/insights/unusual-taxes/","source":"Barnes Roffe"},{"id":"gb-watch","country":"GB","title":"Saat Vergisi","period":"1797–1798","year":1797,"status":"gecmis","group":"Gündelik","motifs":["zaman","lüks","sayım"],"teaser":"Zamana para biçilen bir dönem.","story":"Britanya’da saat ve cep saati sahipliğini hedefleyen kısa ömürlü bir vergi uygulandı; tarihsel vergi listelerinde 1797–1798 olarak yer alır.","url":"https://www.genguide.co.uk/source/taxes-miscellaneous/","source":"GenGuide tarihsel vergi kayıtları"},{"id":"gb-sugar","country":"GB","title":"Şekerli İçecek Harcı","period":"2018–","year":2018,"status":"aktif","group":"Yiyecek","motifs":["şeker","sağlık","davranış"],"teaser":"Şekeri azaltmak, vergi ödemekten daha avantajlı olabilir.","story":"Birleşik Krallık’ta şeker oranı yüksek içeceklerin üretici ve ithalatçılarına yönelik bir harç bulunur. Amaç ürünlerin yeniden formüle edilmesini özendirmektir.","url":"https://www.gov.uk/guidance/check-if-your-drink-is-liable-for-the-soft-drinks-industry-levy","source":"GOV.UK"},{"id":"nl-cycle","country":"NL","title":"Bisiklet Plakası Vergisi","period":"1924–1941","year":1924,"status":"gecmis","group":"Ulaşım","motifs":["bisiklet","plaka","ulaşım"],"teaser":"Pedala basabilmek için metal plaka.","story":"Hollanda’da bisiklet sahipleri yıllık vergi ödüyor, bunu bisiklete takılan metal plaka ile kanıtlıyordu. 1924’te yıllık ücret 3 gulden idi.","url":"https://www.bdmuseum.nl/digitale-reis-door-de-geschiedenis-van-belastingen-in-nederland/","source":"Belasting & Douane Museum"},{"id":"nl-slaughter","country":"NL","title":"Kesim Vergisi","period":"16. yy–1941","year":1590,"status":"gecmis","group":"Hayvan","motifs":["hayvan","ölçüm","gıda"],"teaser":"Hayvanın kuyruğuna kurşun mühür.","story":"Hayvan kesim vergisi hesaplanırken bazı hayvanlar ölçülüyor, değer tahmini yapılıyor ve kontrollerde kuyruklarına mühür takılıyordu.","url":"https://www.bdmuseum.nl/en/exhibitions/bizarre-belastingen/","source":"Belasting & Douane Museum"},{"id":"nl-servant","country":"NL","title":"Hizmetçi Vergisi","period":"1636–1816","year":1636,"status":"gecmis","group":"Toplum","motifs":["servet","ev","sayım"],"teaser":"Evde çalışan kişi sayısı servet işaretiydi.","story":"Hollanda’da ev hizmetlisi istihdam etmek, varlık göstergesi sayılarak vergilendirildi. Evdeki çalışan sayısı mali bir göstergeye dönüştü.","url":"https://www.bdmuseum.nl/en/exhibitions/bizarre-belastingen/","source":"Belasting & Douane Museum"},{"id":"nl-marriage","country":"NL","title":"Evlilik ve Defin Vergisi","period":"1695 / tarihsel","year":1695,"status":"gecmis","group":"Toplum","motifs":["evlilik","ölüm","tören"],"teaser":"Evlenirken de, ölürken de makbuz.","story":"Hollanda’da 1695’ten itibaren evlenme ve defin işlemlerinde kişinin gelirine göre değişen mali yükümlülükler vardı; başka belediyede yapılan işlemler daha pahalı olabiliyordu.","url":"https://www.bdmuseum.nl/en/exhibitions/bizarre-belastingen/","source":"Belasting & Douane Museum"},{"id":"nl-paper","country":"NL","title":"Gazete Damga Vergisi","period":"19. yy–1869","year":1800,"status":"gecmis","group":"Gündelik","motifs":["basın","damga","bilgi"],"teaser":"Haber okumak pahalılaştırıldı.","story":"Hollanda’da gazetelere uygulanan damga vergisi, fiyatları artırdı. 1869’da kaldırılması gazete satışlarının büyümesine yardımcı oldu.","url":"https://www.bdmuseum.nl/en/exhibitions/bizarre-belastingen/","source":"Belasting & Douane Museum"},{"id":"nl-doors","country":"NL","title":"Kapı ve Pencere Vergisi","period":"19. yüzyıl","year":1800,"status":"gecmis","group":"Ev","motifs":["pencere","konut","sayım"],"teaser":"Kapıyı say, pencereyi say, tahsilatı yaz.","story":"Fransız yönetimi döneminde Hollanda’da binaların kapı ve pencere sayıları vergilendirme ölçüsü oldu; kimi insanlar açıklıkları kapattı.","url":"https://www.bdmuseum.nl/en/exhibitions/bizarre-belastingen/","source":"Belasting & Douane Museum"},{"id":"nl-wig","country":"NL","title":"Peruk Pudrası Ruhsatı","period":"19. yüzyıl başı","year":1800,"status":"gecmis","group":"Giyim","motifs":["moda","belge","lüks"],"teaser":"Beyaz saç pudrasına belge.","story":"Hollanda’da Fransız yönetimi döneminde peruk ve saç pudrası gibi lüks kullanımlara vergi uygulandı; kullanıcıların ruhsat gösterebilmesi gerekiyordu.","url":"https://www.bdmuseum.nl/en/exhibitions/bizarre-belastingen/","source":"Belasting & Douane Museum"},{"id":"ru-beard","country":"RU","title":"Sakal Vergisi","period":"1705 / tarihsel","year":1705,"status":"gecmis","group":"Giyim","motifs":["moda","belge","kimlik"],"teaser":"Sakalını tut, jetonunu göster.","story":"Rus Çarı I. Petro döneminde sakal bırakmak isteyen bazı erkekler vergi ödedi. 1705 tarihli sakal jetonları müze koleksiyonlarında bulunuyor.","url":"https://www.si.edu/object/beard-token-russia-1705%3Anmah_993363","source":"Smithsonian"},{"id":"it-bachelor","country":"IT","title":"Bekârlık Vergisi","period":"1927–1943","year":1927,"status":"gecmis","group":"Toplum","motifs":["evlilik","nüfus","ayrımcılık"],"teaser":"Devlet medeni hâli bile vergilendirdi.","story":"1927'de İtalya'da Mussolini yönetimi, 25–65 yaş arasındaki bekâr erkeklere özel bir vergi getirdi. Evliliği ve nüfus artışını teşvik etmeyi amaçlayan bu uygulama 1943'te sona erdi.","url":"https://www.normattiva.it/atto/caricaDettaglioAtto?atto.codiceRedazionale=026U2132&atto.dataPubblicazioneGazzetta=1926-12-24&qId=&tipoDettaglio=originario","source":"Normattiva mevzuat arşivi"},{"id":"it-urine","country":"IT","title":"Roma İdrar Vergisi","period":"MS 1. yüzyıl","year":69,"status":"gecmis","group":"Gündelik","motifs":["hijyen","üretim","atık"],"teaser":"İdrar, çamaşırhane için hammaddeydi.","story":"Roma’da toplanan idrar temizlik ve deri işleme işlerinde kullanılıyordu. Vespasian döneminde bu ticari değere ilişkin vergi anlatıları vardır; tüm tuvalet kullanıcılarından alınan evrensel bir vergi olarak düşünülmemeli.","url":"https://academic.oup.com/edited-volume/43505/chapter/364128738","source":"Oxford Academic"},{"id":"it-venice","country":"IT","title":"Venedik Giriş Ücreti","period":"2026 belirli günler","year":2026,"status":"donemsel","group":"Seyahat","motifs":["turizm","giriş","ziyaretçi"],"teaser":"Bir şehre gündüz girmek için ödeme.","story":"Venedik’in tarihî merkezine belirli gün ve saatlerde günübirlik erişim ücreti uygulandı. 2026 dönemi 26 Temmuz’da bitti; 2027 için yeniden uygulanacağı duyuruldu. Vergiden ziyade erişim katkı payıdır.","url":"https://cda.veneziaunica.it/en","source":"Venezia Unica resmî portalı"},{"id":"fr-gabelle","country":"FR","title":"Tuz Vergisi (Gabelle)","period":"Eski Rejim–1945","year":1547,"status":"gecmis","group":"Yiyecek","motifs":["tuz","gıda","kaçınma"],"teaser":"Tuz, kaçakçılığın başrolündeydi.","story":"Fransa’da tuz satışı ve vergisi bölgelere göre değişiyordu. Gabelle, 1790’da kaldırıldı; sonra yeniden uygulandı ve 1945’te bütünüyle sona erdi.","url":"https://www.economie.gouv.fr/saef/document-du-mois/la-gabelle-et-les-taxes-sur-le-sel-une-longue-histoire","source":"Fransa Ekonomi Bakanlığı"},{"id":"fr-windows","country":"FR","title":"Kapı ve Pencere Vergisi","period":"1798–","year":1798,"status":"gecmis","group":"Ev","motifs":["pencere","konut","sayım"],"teaser":"Binanın açıklıkları vergi matrahı oldu.","story":"Fransa’da 1798’de getirilen vergi, kapı ve pencereleri sayarak taşınmazlardan gelir toplamayı amaçladı.","url":"https://www.economie.gouv.fr/saef/fiscalite-historique","source":"Fransa Ekonomi Bakanlığı"},{"id":"jp-onsen","country":"JP","title":"Kaplıcaya Girme Vergisi","period":"Güncel","year":2026,"status":"aktif","group":"Gündelik","motifs":["kaplıca","turizm","sağlık"],"teaser":"Sıcak suya girince belediye payı.","story":"Japonya’da bazı belediyeler mineral kaplıca kullanıcılarından giriş vergisi alır. Örneğin Sumida’da 2026 itibarıyla kişi başı günlük 150 yen ve belirli muafiyetler vardır.","url":"https://www.city.sumida.lg.jp/kurashi/zeikin/tobacco_bath/nyuutouzei.html","source":"Sumida Belediyesi"},{"id":"jp-exit","country":"JP","title":"Uluslararası Çıkış Vergisi","period":"2019–","year":2019,"status":"aktif","group":"Seyahat","motifs":["çıkış","havalimanı","yolculuk"],"teaser":"Uçuş biletinin içinde çıkış vergisi.","story":"Japonya’da çoğu uluslararası yolcu için ülkeden ayrılışta ulusal çıkış vergisi uygulanır. Tutar ve istisnalar döneme ve bilet düzenlenme tarihine bağlı olabilir.","url":"https://www.nta.go.jp/english/taxes/indirect/basic_knowledge.htm","source":"Japonya Ulusal Vergi Dairesi"},{"id":"tr-exit","country":"TR","title":"Yurt Dışına Çıkış Harcı","period":"Güncel","year":2026,"status":"aktif","group":"Seyahat","motifs":["çıkış","havalimanı","yolculuk"],"teaser":"Pasaport, bilet… bir de çıkış harcı.","story":"Türkiye’de bazı istisnalar dışında yurt dışına çıkan kişiler için ayrıca harç ödenir. Tutar ve muafiyetler mevzuatla belirlenir.","url":"https://gib.gov.tr/mevzuat/kanun/455/teblig/11846","source":"Gelir İdaresi Başkanlığı"},{"id":"ie-bag","country":"IE","title":"Plastik Poşet Harcı","period":"2002–","year":2002,"status":"aktif","group":"Çevre","motifs":["poşet","atık","davranış"],"teaser":"Poşet bedava olmaktan çıktı.","story":"İrlanda 2002’de plastik alışveriş poşetlerine çevre harcı getirdi. Amaç kullanımı azaltmaktı; gelir zamanla azalırken poşet tüketimi de düştü.","url":"https://www.revenue.ie/en/companies-and-charities/plastic-bag-environmental-levy/index.aspx","source":"Ireland Revenue"},{"id":"in-salt","country":"IN","title":"Tuz Vergisi ve Yürüyüşü","period":"1930 dönüm noktası","year":1930,"status":"gecmis","group":"Yiyecek","motifs":["tuz","gıda","direniş"],"teaser":"Bir avuç tuz siyaseti değiştirdi.","story":"Britanya sömürge yönetiminin tuz düzenlemelerine karşı Gandhi’nin 1930’daki Tuz Yürüyüşü sivil itaatsizliğin simgesi oldu. Hindistan’ın bağımsızlık tarihi açısından önemlidir.","url":"https://ideas.repec.org/h/spr/sptchp/978-3-030-68214-9_5.html","source":"Akademik tarih bölümü"},{"id":"hu-chips","country":"HU","title":"Cips Vergisi","period":"2011–","year":2011,"status":"aktif","group":"Yiyecek","motifs":["şeker","tuz","sağlık"],"teaser":"Cips ve şekerli ürünlere özel sağlık vergisi.","story":"Macaristan 2011’de şekerli içecekler, enerji içecekleri ve bazı yüksek tuz veya şekerli ambalajlı ürünlere halk sağlığı vergisi getirdi.","url":"https://eurohealthobservatory.who.int/monitors/health-systems-monitor/updates/hspm/hungary-2011/taxation-on-high-risk-products-used-to-boost-health-system-revenue-and-improve-health-status","source":"WHO Avrupa Gözlemevi"},{"id":"ug-social","country":"UG","title":"Sosyal Medya Vergisi","period":"2018–2021","year":2018,"status":"gecmis","group":"Teknoloji","motifs":["internet","iletişim","erişim"],"teaser":"WhatsApp açmanın günlük maliyeti.","story":"Uganda’da 2018’de belirli sosyal medya hizmetlerine erişim için günlük 200 şilinlik OTT vergisi getirildi. Bu vergi 1 Temmuz 2021’de kaldırıldı.","url":"https://www.mtn.co.ug/customer-notice-cessation-of-over-the-top-ott-tax/","source":"MTN Uganda 2021 duyurusu"},{"id":"za-sugar","country":"ZA","title":"Şeker Gramı Vergisi","period":"2018–","year":2018,"status":"aktif","group":"Yiyecek","motifs":["şeker","sağlık","davranış"],"teaser":"İçecekteki şekeri gram gram hesapla.","story":"Güney Afrika’nın 2018’den itibaren uyguladığı sağlık teşvik harcı, içeceklerde belirli bir eşik üzerindeki şeker gramına göre hesaplanır.","url":"https://www.sars.gov.za/customs-and-excise/excise/health-promotion-levy-on-sugary-beverages/","source":"South African Revenue Service"},{"id":"mx-sugar","country":"MX","title":"Gazlı İçecek Vergisi","period":"2014–","year":2014,"status":"aktif","group":"Yiyecek","motifs":["şeker","sağlık","davranış"],"teaser":"Şekerli içeceğin litresine vergi.","story":"Meksika 2014’te ilave şekerli içeceklere litre başına özel tüketim vergisi getirdi; uygulama, satın alma davranışı üzerine araştırmalara konu oldu.","url":"https://portal.insp.mx/control-tabaco/reportes/proposed-tax-redesign-for-sugar-sweetened-beverages","source":"Meksika Ulusal Halk Sağlığı Enstitüsü"},{"id":"co-bag","country":"CO","title":"Poşet Tüketim Vergisi","period":"2017–","year":2017,"status":"aktif","group":"Çevre","motifs":["poşet","atık","davranış"],"teaser":"Alışveriş poşeti ayrı vergi kalemi.","story":"Kolombiya’da 1 Temmuz 2017’den itibaren alışveriş poşetleri için ulusal tüketim vergisi getirildi; bazı istisnalar bulunuyor.","url":"https://cancilleria.gov.co/sites/default/files/Normograma/docs/estatuto_tributario_pr020.htm","source":"Kolombiya Vergi Kanunu"},{"id":"us-blueberry","country":"US","title":"Yaban Mersini Vergisi","period":"Maine · güncel","year":2026,"status":"aktif","group":"Yiyecek","motifs":["tarım","üretim","meyve"],"teaser":"Yaban mersini pound başına vergilendiriliyor.","story":"Maine eyaleti işlenen veya eyalet dışına gönderilen yabani yaban mersinine pound başına 1,5 sent özel vergi koyar. Üretici ve sevkiyatçıların yükümlülükleri yasada belirtilir.","url":"https://legislature.maine.gov/statutes/36/title36sec4303.html","source":"Maine Eyalet Mevzuatı"},{"id":"us-bagel","country":"US","title":"Hazırlanmış Bagel Satış Vergisi","period":"New York · güncel","year":2026,"status":"aktif","group":"Yiyecek","motifs":["hazırlama","gıda","satış"],"teaser":"Bagel aynı, servis şekli farklı.","story":"New York’ta paket hâlinde satılan sade bagel ile tost edilmiş veya üzerine peynir sürülerek hazırlanmış bagel farklı satış vergisi kurallarına tabi olabilir. Sırf dilimlemek tek başına vergiyi belirlemez.","url":"https://www.tax.ny.gov/pubs_and_bulls/tg_bulletins/st/food_sold_by_food_stores.htm","source":"New York Tax Department"},{"id":"us-cards","country":"US","title":"Oyun Kâğıdı Vergisi","period":"Alabama · tarihî","year":1935,"status":"gecmis","group":"Gündelik","motifs":["oyun","damga","eğlence"],"teaser":"Alabama’da kâğıt destesi için özel vergi.","story":"Alabama’da oyun kâğıdı destelerine özel vergi uygulanmıştı; bu verginin tahsilatını askıya alma yetkisi 2014’te düzenlendi.","url":"https://alison.legislature.state.al.us/files/pdfdocs/lsa/Fiscal/TaxGuide/2019_Tax_Guide.pdf","source":"Alabama Tax Guide"},{"id":"de-dog","country":"DE","title":"Köpek Vergisi","period":"Berlin · güncel","year":2026,"status":"aktif","group":"Hayvan","motifs":["hayvan","evcil","belediye"],"teaser":"Köpeğin için yıllık beyan.","story":"Berlin’de ilk köpek için yıllık 120 €, sonraki köpeklerin her biri için 180 € köpek vergisi alınıyor. Köpek kayıt sistemi ve vergi bildirimi ayrı kurallara tabi.","url":"https://www.berlin.de/sen/finanzen/steuern/informationen-fuer-steuerzahler-/faq-steuern/artikel.8848.php","source":"Berlin Maliye İdaresi"},{"id":"ch-dog","country":"CH","title":"Kanton Köpek Vergileri","period":"Güncel","year":2026,"status":"aktif","group":"Hayvan","motifs":["hayvan","evcil","belediye"],"teaser":"Köpeğin vergisi yaşadığın belediyeye göre değişiyor.","story":"İsviçre’de köpek sahipleri için kanton veya belediye düzeyinde yıllık yükümlülükler bulunur; tutar ve muafiyetler yerel kurallara göre değişebilir.","url":"https://www.ch.ch/en/taxes-and-finances/types-of-taxation/","source":"İsviçre kamu bilgi portalı"},{"id":"dk-methane","country":"DK","title":"Çiftlik Metanı Vergisi","period":"2030 için planlandı","year":2030,"status":"plan","group":"Çevre","motifs":["hayvan","emisyon","iklim"],"teaser":"İneklerin sindiriminden çıkan metan gündemde.","story":"Danimarka’da 2024 anlaşması kapsamında çiftlik hayvanlarının sindiriminden ve gübre yönetiminden kaynaklanan sera gazlarına 2030’dan itibaren vergi getirilmesi planlanıyor. 2026 itibarıyla henüz yürürlükte değil.","url":"https://klimaraadet.dk/da/virkemiddel/generel-ensartet-drivhusgasafgift","source":"Danimarka İklim Konseyi"},{"id":"ca-head","country":"CA","title":"Çinli Göçmenlere Baş Vergisi","period":"1885–1923","year":1885,"status":"gecmis","group":"Toplum","motifs":["göç","ayrımcılık","kimlik"],"teaser":"Vergilendirilen şey bir insanın kökeniydi.","story":"Kanada’da Çinli göçmenlere ayrımcı biçimde uygulanan baş vergisi 1885’te 50 dolardı, 1903’te 500 dolara yükseldi. Bu kayıt tarihsel bir haksızlıktır; mizahi bir uygulama değildir.","url":"https://www.canada.ca/en/canadian-heritage/campaigns/asian-heritage-month/important-events.html","source":"Kanada Hükûmeti"},{"id":"ca-carbon","country":"CA","title":"Karbon Vergisinin Kaldırılması","period":"British Columbia · 2025","year":2025,"status":"gecmis","group":"Çevre","motifs":["iklim","emisyon","yakıt"],"teaser":"Yıllardır alınan verginin oranı sıfırlandı.","story":"British Columbia’da tüketici karbon vergisi 1 Nisan 2025’te kaldırıldı. Endüstriyel büyük salımcılar için ayrı fiyatlama düzenlemeleri devam ediyor.","url":"https://www2.gov.bc.ca/gov/content/taxes/sales-taxes/motor-fuel-carbon-tax","source":"British Columbia Yönetimi"},{"id":"nz-visitor","country":"NZ","title":"Ziyaretçi Koruma Harcı","period":"2024–","year":2024,"status":"aktif","group":"Seyahat","motifs":["turizm","giriş","ziyaretçi"],"teaser":"Turist olmanın çevre katkısı.","story":"Yeni Zelanda, uygun vize veya NZeTA başvurularında uluslararası ziyaretçilerden 100 NZD koruma ve turizm harcı topluyor; belirli muafiyetler var.","url":"https://www.immigration.govt.nz/process-to-apply/applying-for-a-visa/fees-processing-times-and-refunds/paying-the-international-visitor-levy/","source":"Immigration New Zealand"},{"id":"ph-travel","country":"PH","title":"Seyahat Vergisi","period":"Güncel","year":2026,"status":"aktif","group":"Seyahat","motifs":["çıkış","havalimanı","yolculuk"],"teaser":"Ülkeden ayrılırken seyahat vergisi.","story":"Filipinler’de kapsam dahilindeki uluslararası yolculardan ayrıca seyahat vergisi alınır. Ekonomi sınıfında standart tutar 1.620 PHP’dir; muafiyetler ve indirimler vardır.","url":"https://tieza.gov.ph/travel-tax/","source":"TIEZA, Filipinler"},{"id":"au-departure","country":"AU","title":"Yolcu Hareket Harcı","period":"Güncel","year":2026,"status":"aktif","group":"Seyahat","motifs":["çıkış","havalimanı","yolculuk"],"teaser":"Uluslararası çıkış başına ayrı ücret.","story":"Avustralya’dan uluslararası seyahat eden yolcular için Passenger Movement Charge bulunur; çoğunlukla bilet ücretinin içinde tahsil edilir.","url":"https://www.abf.gov.au/entering-and-leaving-australia/crossing-the-border/passenger-movement/passenger-movement-charge-%28pmc%29","source":"Australian Border Force"},{"id":"tr-trt-bandrol","country":"TR","title":"TRT Bandrol Ücreti","period":"1984–günümüz","year":1984,"status":"aktif","group":"Teknoloji","motifs":["bandrol","medya","cihaz"],"teaser":"Telefon alıyorsun, TRT payı cihazın içinde.","story":"Yayın alabilen cihazların üretim ve ithalatında TRT bandrol ücreti bulunur. TRT’nin yayımladığı listede televizyon ve radyoda %16, cep telefonu ve SIM özellikli akıllı saatte %12, bilgisayar ve tablette %4 oranı yer alır. Elektrik faturalarından kaldırılan TRT payından farklı bir kalemdir.","url":"https://www.trt.net.tr/bandrol/aciklamalar","source":"TRT Bandrol / resmî açıklamalar","type":"Bandrol ücreti"},{"id":"tr-trt-electric","country":"TR","title":"Elektrik Faturasındaki TRT Payı","period":"1984–2021","year":1984,"status":"gecmis","group":"Enerji","motifs":["elektrik","trt","enerji","fatura","medya"],"teaser":"Bir dönem ampul yakmak da TRT’ye gelir sağlıyordu.","story":"Elektrik enerjisi satışından alınan TRT payı, 7346 sayılı Kanun uyarınca 1 Ocak 2022’den itibaren kaldırıldı. Bugün elektrik faturasında bu adla devam eden bir kesinti yoktur. Cihaz bandrolü ise ayrı bir gelir türü olarak sürüyor.","url":"https://www.tbmm.gov.tr/Yasama/Kanun/f72877c1-f81f-037b-e050-007f01005610","source":"TBMM / 7346 sayılı Kanun","type":"Pay · kaldırıldı"},{"id":"tr-energy-fund","country":"TR","title":"Elektrik Enerji Fonu Kesintisi","period":"2021 sonuna kadar","year":1990,"status":"gecmis","group":"Enerji","motifs":["elektrik","enerji","fatura","fon"],"teaser":"Faturadaki bir başka satır: Enerji Fonu.","story":"Elektrik faturalarına yansıyan Enerji Fonu kesintisi, TRT payıyla birlikte 1 Ocak 2022’de kaldırıldı. TRT payıyla aynı şey değildi; geçmiş faturaların farklı iki kalemiydi.","url":"https://www.aa.com.tr/tr/ekonomi/trt-payi-ve-enerji-fonunun-kaldirilmasiyla-meskenlerin-elektrik-faturasi-yillik-930-milyon-lira-azalacak/2415757","source":"Anadolu Ajansı / değişiklik haberi","type":"Fon kesintisi · kaldırıldı"},{"id":"tr-electric-tax","country":"TR","title":"Elektrik ve Havagazı Tüketim Vergisi","period":"1981–günümüz","year":1981,"status":"aktif","group":"Enerji","motifs":["elektrik","enerji","fatura","belediye"],"teaser":"TRT gitti; elektrik vergisi tamamen gitmedi.","story":"Belediye Gelirleri Kanunu kapsamındaki elektrik ve havagazı tüketim vergisi, elektrik tüketimi için hâlâ ayrı bir yükümlülüktür. 2026 Gelir İdaresi vergi takviminde beyan ve ödeme başlığı yer alır.","url":"https://gib.gov.tr/vergi-takvimi?selectedDate=2026-10-20","source":"Gelir İdaresi / 2026 vergi takvimi","type":"Belediye vergisi"},{"id":"tr-special-com","country":"TR","title":"Özel İletişim Vergisi","period":"1999–günümüz","year":1999,"status":"aktif","group":"Teknoloji","motifs":["telefon","internet","iletişim","abonelik"],"teaser":"Konuşmanın ve internete bağlanmanın vergi kalemi.","story":"1999 sonrası yürürlüğe giren özel iletişim vergisi, kapsam dahilindeki elektronik haberleşme hizmetlerine uygulanır. Cep telefonu aboneliğinin ilk tesisi için ayrıca maktu vergi bulunur; günlük kullanım vergisiyle karıştırılmamalıdır.","url":"https://gib.gov.tr/mevzuat/kanun/445/teblig/11850","source":"Gelir İdaresi / ÖİV Genel Tebliği","type":"Vergi"},{"id":"tr-new-line","country":"TR","title":"Yeni Telefon Hattı Açılış Vergisi","period":"2026","year":2026,"status":"aktif","group":"Teknoloji","motifs":["telefon","sim","abonelik","iletişim"],"teaser":"Yeni hat açınca daha ilk konuşmadan vergi.","story":"2026 yılında mobil telefon aboneliğinin ilk tesisi için maktu özel iletişim vergisi 700 TL olarak belirlenmiştir. Operatör değişiklikleri ve mevzuattaki bazı makineden makineye iletişim halleri bu ilk tesis kalemi dışında tutulur.","url":"https://gib.gov.tr/mevzuat/kanun/445/teblig/11850","source":"Gelir İdaresi / ÖİV Genel Tebliği (2026)","type":"Maktu vergi"},{"id":"tr-imei","country":"TR","title":"Yurt Dışı Telefon Kayıt Harcı","period":"2012–günümüz","year":2012,"status":"aktif","group":"Teknoloji","motifs":["telefon","imei","seyahat","kayıt"],"teaser":"Telefonu getirdin. Kullanmak ayrı bir işlem.","story":"Yolcuların kendi kullanımına yönelik yurt dışından getirdiği telefonların Türkiye şebekelerinde kullanım izni için harç ödenir. IMEI kaydından önce tahsil edilen bu harç yıllara göre yeniden belirlenir; tüm telefon alımlarının vergisi değildir.","url":"https://gib.gov.tr/mevzuat/kanun/439/icgenelge/482","source":"Gelir İdaresi / telefon kullanım izin harcı","type":"Harç"},{"id":"tr-accommodation","country":"TR","title":"Konaklama Vergisi","period":"2023–günümüz","year":2023,"status":"aktif","group":"Seyahat","motifs":["otel","konaklama","turizm","geceleme"],"teaser":"Geceyi otelde geçirmek de ayrıca vergili.","story":"Otel, pansiyon, kamping gibi kapsama giren tesislerde geceleme hizmeti konaklama vergisine tabidir. 1 Mayıs–31 Aralık 2026 arasında oran %1 uygulanmaktadır; normal yasal oran %2’dir. Tesis faturasındaki ayrı bir kalemdir.","url":"https://kars.gib.gov.tr/mevzuat/kanun/445","source":"Gelir İdaresi / Gider Vergileri Kanunu 34. madde","type":"Vergi"},{"id":"tr-plastic-bag","country":"TR","title":"Ücretli Plastik Poşet","period":"2019–günümüz","year":2019,"status":"aktif","group":"Çevre","motifs":["poşet","plastik","atık","alışveriş"],"teaser":"Marketten çıkan poşetin resmî fiyatı var.","story":"Plastik alışveriş poşetlerinin ücretlendirilmesi 2019’da başladı. 2026’da kapsamdaki poşetler için vergiler dâhil satış ücreti adet başına 1 TL olarak belirlendi. Bu bir perakende satış ücreti uygulamasıdır; doğrudan poşet vergisi diye sınıflandırmak doğru olmaz.","url":"https://cygm.csb.gov.tr/plastik-posetlerin-ucretlendirilmesine-iliskin-usul-ve-esaslar-da-guncelleme-yapildi-duyuru-469175","source":"Çevre, Şehircilik ve İklim Değişikliği Bakanlığı","type":"Zorunlu ücret · vergi değil"},{"id":"tr-gekap","country":"TR","title":"Geri Kazanım Katılım Payı (GEKAP)","period":"2019–günümüz","year":2019,"status":"aktif","group":"Çevre","motifs":["plastik","ambalaj","atık","üretim"],"teaser":"Ürünü piyasaya sürmek, geri dönüşüm yükümlülüğü doğuruyor.","story":"Çevre Kanunu kapsamında belirli poşet ve ambalaj ürünleri için piyasaya sürme/ithalat aşamasında geri kazanım katılım payı alınır. Poşette satış noktası, diğer ürünlerde üretici veya ithalatçı sorumlu olabilir; tüketicinin ödediği poşet ücretiyle aynı kalem değildir.","url":"https://csb.gov.tr/sss-detay/1655","source":"Çevre Bakanlığı / GEKAP sık sorulan sorular","type":"Katılım payı"},{"id":"tr-digital-service","country":"TR","title":"Dijital Hizmet Vergisi","period":"2020–günümüz","year":2020,"status":"aktif","group":"Teknoloji","motifs":["dijital","internet","platform","oyun"],"teaser":"Çevrimiçi oyun ve reklam hasılatı da vergi konusu.","story":"Türkiye’de şartları sağlayan dijital reklam, dijital içerik, oyun ve platform hizmetlerinin hasılatı üzerinden dijital hizmet vergisi uygulanır. 2026 itibarıyla oran %5’tir; 2027 için %2,5 oranı belirlenmiştir. Her internet kullanıcısından ayrı ayrı tahsil edilen bir vergi değildir.","url":"https://www.gib.gov.tr/mevzuat/kanun/465","source":"Gelir İdaresi / Dijital Hizmet Vergisi Kanunu","type":"Vergi"},{"id":"tr-luxury-home","country":"TR","title":"Değerli Konut Vergisi","period":"2021–günümüz","year":2021,"status":"aktif","group":"Ev","motifs":["konut","servet","emlak"],"teaser":"Evin vergisi var; çok değerliyse bir vergi daha.","story":"Emlak vergisi değerine göre belirlenen eşiği aşan mesken nitelikli taşınmazlar için değerli konut vergisi düzenlenmiştir. 2026 yılında değer sınırları güncellenmiştir. Her ev için değil, kapsam içindeki değerli meskenler için uygulanır.","url":"https://gib.gov.tr/yardim-ve-kaynaklar/yayinlar","source":"Gelir İdaresi / 2026 değerli konut vergisi rehberi","type":"Vergi"},{"id":"tr-waste","country":"TR","title":"Çevre Temizlik Vergisi","period":"1993–günümüz","year":1993,"status":"aktif","group":"Ev","motifs":["su","atık","belediye","konut"],"teaser":"Çöpler için vergi, konutta suya göre hesap.","story":"Belediye sınırları içindeki hizmetlerden yararlanan konutlarda çevre temizlik vergisi su tüketim miktarıyla bağlantılı hesaplanır. İşyeri ve diğer binalar için ayrı tarife kuralları vardır.","url":"https://rize.gib.gov.tr/mevzuat/kanun/449","source":"Gelir İdaresi / Belediye Gelirleri Kanunu","type":"Belediye vergisi"},{"id":"tr-entertainment","country":"TR","title":"Eğlence Vergisi","period":"1981–günümüz","year":1981,"status":"aktif","group":"Gündelik","motifs":["eğlence","bilet","sinema","belediye"],"teaser":"Eğlenmek de yerel maliyenin konusu.","story":"Belediye Gelirleri Kanunu eğlence yerleri ve belirli faaliyetler için eğlence vergisi düzenler. Kapsam, vergi oranı ve muafiyetler faaliyete göre değişir; her etkinlik için aynı vergi geçerli değildir.","url":"https://gib.gov.tr/mevzuat/kanun/449/teblig/11133","source":"Gelir İdaresi / belediye gelirleri","type":"Belediye vergisi"},{"id":"tr-advertising","country":"TR","title":"İlan ve Reklam Vergisi","period":"1981–günümüz","year":1981,"status":"aktif","group":"Gündelik","motifs":["reklam","belediye","tabela"],"teaser":"Tabela asmak da belediyenin defterine giriyor.","story":"Belediye sınırlarında kanunda belirtilen ilan ve reklam faaliyetleri için ilan ve reklam vergisi uygulanır. Tabela, afiş ve ilan türleri için farklı tarifeler bulunur.","url":"https://gib.gov.tr/mevzuat/kanun/449/teblig/11133","source":"Gelir İdaresi / belediye gelirleri","type":"Belediye vergisi"},{"id":"tr-lottery","country":"TR","title":"Şans Oyunları Vergisi","period":"2007–günümüz","year":2007,"status":"aktif","group":"Gündelik","motifs":["çekiliş","oyun","bahis","şans"],"teaser":"Kazanırsan başka, oyunu düzenlersen başka vergi.","story":"5602 sayılı Kanun kapsamında şans oyunu düzenleyicilerinin elde ettiği hasılat vergiye tabidir. Spor bahisleri, at yarışı ve diğer şans oyunlarında oranlar farklıdır. Bu vergi kazanan kişinin ikramiye vergisiyle karıştırılmamalıdır.","url":"https://gib.gov.tr/mevzuat/kanun/456","source":"Gelir İdaresi / Şans Oyunları Kanunu","type":"İşletmeci vergisi"},{"id":"tr-prize","country":"TR","title":"Çekilişte Kazanılan Hediyenin Vergisi","period":"Güncel","year":2026,"status":"aktif","group":"Gündelik","motifs":["çekiliş","hediye","şans","ödül"],"teaser":"Bedava araba kazanmak, her zaman sıfır maliyet değil.","story":"Çekiliş ve yarışmalarda kazanılan para veya mal ödülleri, kanundaki istisna tutarını aştığında veraset ve intikal vergisine tabi olabilir. 2026’da çekiliş ikramiyeleri için istisna 66.935 TL olarak belirtilmiştir. Kural her gündelik hediye için geçerli değildir.","url":"https://kayseri.gib.gov.tr/vergi-konulari/1_bireysel/12_veraset_ve_intikal_vergisi/12","source":"Gelir İdaresi / 2026 veraset ve intikal rehberi","type":"İntikal vergisi"},{"id":"tr-aghnam","country":"TR","title":"Ağnam: Koyun ve Keçi Vergisi","period":"Osmanlı–1962","year":1500,"status":"gecmis","group":"Hayvan","motifs":["koyun","keçi","hayvan","sayım"],"teaser":"Meclisin ilk kanunu koyun vergisi hakkındaydı.","story":"Ağnam resmi, Osmanlı’da koyun ve keçiler üzerinden alınan vergilerin genel adıdır. TBMM’nin açılıştan sonra kabul ettiği ilk kanun da 24 Nisan 1920’de Ağnam Resmi Kanunu oldu. Hayvan vergilerinin bazı devam biçimleri 1962’ye kadar sürdü.","url":"https://sozluk.ttk.gov.tr/detay/5194/%C3%82det-i-A%C4%9Fn%C3%A2m/A%C4%9Fn%C3%A2m-Resmi-%28%D8%A7%D8%BA%D9%86%D8%A7%D9%85-%D8%B1%D8%B3%D9%85%D9%89/%D8%B9%D8%A7%D8%AF%D8%AA-%D8%A7%D8%BA%D9%86%D8%A7%D9%85%29","source":"Türk Tarih Kurumu / tarih sözlüğü","type":"Tarihsel vergi"},{"id":"tr-arus","country":"TR","title":"Resm-i Arûs: Evlilik Harcı","period":"Osmanlı / Tanzimat öncesi","year":1600,"status":"gecmis","group":"Toplum","motifs":["evlilik","tören","aile","gelin"],"teaser":"Düğünün bir kalemi de evlenme resmiydi.","story":"Osmanlı kanunnamelerinde resm-i arûs, evlenen kadınlar üzerinden alınan örfî bir harç olarak geçer. Nikâh tescilindeki ücretten ayrıydı; tarihsel ve toplumsal koşullarıyla ele alınmalıdır.","url":"https://sozluk.ttk.gov.tr/detay/6478/Resm-i-Ar%C3%BBs-%28%D8%B1%D8%B3%D9%85%E2%80%AF%D8%B9%D8%B1%D9%88%D8%B3%29","source":"Türk Tarih Kurumu / Resm-i Arûs","type":"Tarihsel harç"},{"id":"tr-oshur","country":"TR","title":"Öşür / Aşar Vergisi","period":"Osmanlı–1925","year":1500,"status":"gecmis","group":"Yiyecek","motifs":["tarım","ürün","hasat","buğday"],"teaser":"Buğday yetiştir, hasadın payı vergi olsun.","story":"Osmanlı’da tarımsal ürünler, özellikle tahıllar üzerinden alınan öşür/aşar, çoğu zaman ürün olarak da tahsil edilirdi. Tahsil şekli ve oranı bölgeye ve döneme göre değişti. Türkiye Cumhuriyeti’nde aşar vergisi 1925’te kaldırıldı.","url":"https://sozluk.ttk.gov.tr/detay/6450/%C3%96%C5%9F%C3%BCr-%28%D8%B9%D8%B4%D8%B1%29","source":"Türk Tarih Kurumu / Öşür maddesi","type":"Tarihsel vergi"},{"id":"fr-dog","country":"FR","title":"Köpek Vergisi","period":"1855–1971","year":1855,"status":"gecmis","group":"Hayvan","motifs":["köpek","hayvan","belediye","sayım"],"teaser":"Köpek besliyorsan belediyeye bildir ve vergisini öde.","story":"Fransa'da 1855 tarihli kanun belediyelere köpekler için vergi alma yetkisi verdi. Köpek türü ve kullanımına göre tarifeler farklılaşıyordu; sahipler belediyeye beyanda bulunuyordu. Bu uygulama 1971'de kaldırıldı.","url":"https://francearchives.gouv.fr/facomponent/f0addc12ac3b5d03a9168fe18b142953c304e0d5","source":"FranceArchives / Fransız arşivleri","type":"Tarihsel belediye vergisi"},{"id":"fr-shed","country":"FR","title":"Bahçe Kulübesi ve Havuz Vergisi","period":"2026 / güncel","year":2026,"status":"aktif","group":"Ev","motifs":["bahçe","konut","havuz","inşaat"],"teaser":"Bahçeye küçük kulübe kurmak bile vergi doğurabilir.","story":"Fransa'da taxe d'aménagement, izin gerektiren bazı yapı ve ek tesisler için tahsil edilen bir defalık yerel vergidir. Kapalı bahçe kulübesi, veranda ve havuzlar kapsam dahilinde olabilir. Her açık teras veya pergola bu vergiye tabi değildir.","url":"https://www.service-public.gouv.fr/particuliers/actualites/A15416","source":"Service Public / 2026 imar vergisi","type":"Yerel imar vergisi"},{"id":"fr-tv","country":"FR","title":"Televizyon Ruhsat Payı","period":"–2021 (2022'de kaldırıldı)","year":1980,"status":"gecmis","group":"Teknoloji","motifs":["trt","medya","cihaz","televizyon"],"teaser":"Evin televizyonu için kamu yayın payı.","story":"Fransa'da contribution à l'audiovisuel public adı verilen kamu yayın katkısı, televizyon sahipliğiyle ilişkiliydi ve ikamet vergisi bildirimleriyle birlikte yer alabiliyordu. 2022'den itibaren hem bireyler hem işletmeler için kaldırıldı.","url":"https://www.impots.gouv.fr/suppression-de-la-contribution-laudiovisuel-public-des-2022","source":"Fransız Vergi İdaresi / 2022 kaldırma duyurusu","type":"Yayın katkı payı · kaldırıldı"},{"id":"fr-soda","country":"FR","title":"Şekerli İçecekte Şeker Miktarı Vergisi","period":"2012–günümüz","year":2012,"status":"aktif","group":"Yiyecek","motifs":["şeker","sağlık","içecek","davranış"],"teaser":"Şeker miktarına göre içeceğin vergisi değişiyor.","story":"Fransa'da ilave şekerli veya bazı tatlandırıcılı içeceklere özel katkı payı uygulanır. 2026 tarifesinde, içecekteki ilave şeker miktarına göre farklı eşikler bulunur; tatlandırıcı içeren içecekler için ayrı tarife vardır.","url":"https://entreprendre.service-public.gouv.fr/vosdroits/F32101","source":"Service Public / içecek vergileri 2026","type":"Tüketim katkı payı"},{"id":"sg-casino","country":"SG","title":"Kumarhane Giriş Harcı","period":"2010–günümüz","year":2010,"status":"aktif","group":"Gündelik","motifs":["giriş","eğlence","harç"],"teaser":"Kumarhaneye girmek, herkes için aynı fiyat değil.","story":"Singapur vatandaşı ve daimî oturum sahipleri kumarhaneye giriş için 24 saatlik 150 SGD veya yıllık 3.000 SGD harç ödüyor. Yabancı turistler aynı giriş harcına tabi değil. Uygulama sosyal riskleri sınırlamaya yönelik.","url":"https://sso.agc.gov.sg/Act/CCA2006?ProvIds=P16-","source":"Singapore Statutes Online","type":"Giriş harcı"},{"id":"sg-helper","country":"SG","title":"Evde Çalışan Göçmen İşçi Harcı","period":"Güncel","year":2026,"status":"aktif","group":"Toplum","motifs":["istihdam","ev","çalışma","harç"],"teaser":"Evde yardımcı çalıştıran işveren her ay ayrıca harç ödüyor.","story":"Singapur'da göçmen ev işçisi çalıştıran işverenin aylık levy ödeme yükümlülüğü vardır. İlk yardımcı için normal tutar 300 SGD, sonraki için 450 SGD; uygun bakım ihtiyacı bulunan hanelere 60 SGD indirimli tutar uygulanabilir. Harç çalışandan değil işverenden tahsil edilir.","url":"https://www.mom.gov.sg/passes-and-permits/work-permit-for-foreign-domestic-worker/foreign-domestic-worker-levy/paying-levy","source":"Singapur Çalışma Bakanlığı","type":"İşveren harcı"},{"id":"id-bali","country":"ID","title":"Bali Turist Koruma Harcı","period":"2024–günümüz","year":2024,"status":"aktif","group":"Seyahat","motifs":["turizm","giriş","kültür","koruma"],"teaser":"Bali'ye girerken kültür ve doğaya ayrı katkı.","story":"Endonezya'nın Bali eyaletinde yabancı turistlerden ziyaret başına 150.000 rupiah alınır. 14 Şubat 2024'te başlayan düzenleme kültürel ve doğal mirasın korunması için yürürlüktedir; tüm Endonezya'ya uygulanan bir giriş vergisi değildir.","url":"https://disnakeresdm.baliprov.go.id/greeting-from-the-governor-of-bali/","source":"Bali Eyalet Yönetimi, 2026","type":"Yerel turist harcı"},{"id":"bt-sdf","country":"BT","title":"Gecelik Sürdürülebilirlik Ücreti","period":"2022–günümüz","year":2022,"status":"aktif","group":"Seyahat","motifs":["turizm","doğa","geceleme","harç"],"teaser":"Bhutan'da bir gece kalmak için günlük katkı payı.","story":"Bhutan'da çoğu yabancı yetişkin ziyaretçi için sürdürülebilir kalkınma bedeli 100 USD/gece. Hint ziyaretçiler için 1.200 INR/gece ayrı tarife var; çocuklara indirim ve muafiyet uygulanıyor. Otel faturası veya giriş vizesiyle aynı kalem değil.","url":"https://bhutan.travel/visa","source":"Bhutan Resmî Turizm Portalı","type":"Sürdürülebilirlik bedeli"},{"id":"mv-green","country":"MV","title":"Tatilciye Gecelik Yeşil Vergi","period":"2015–günümüz","year":2015,"status":"aktif","group":"Çevre","motifs":["turizm","geceleme","doğa","harç"],"teaser":"Tatil adasında her gün ayrıca yeşil vergi.","story":"Maldivler'in Green Tax uygulamasında 1 Ocak 2025'ten beri çoğu turistik tesiste konaklayan yabancı ziyaretçiler için kişi başı gecelik 12 USD, yerleşimli adalarda 50 odadan az/50 odalı bazı küçük konaklama tesislerinde 6 USD alınır. İki yaşından küçükler muaftır.","url":"https://mira.gov.mv/Pages/View/whatisgreentax","source":"Maldives Inland Revenue Authority","type":"Çevre vergisi"},{"id":"se-bag","country":"SE","title":"Plastik Poşet Vergisi","period":"2020–2024","year":2020,"status":"gecmis","group":"Çevre","motifs":["poşet","plastik","atık","davranış"],"teaser":"Üç kronluk poşet vergisi dört yılda tarih oldu.","story":"İsveç'te 2020'de getirilen plastik taşıma çantası vergisi çoğu poşette adet başına 3 krondu. Poşet kullanımındaki büyük düşüş sonrasında vergi 1 Kasım 2024'te kaldırıldı. Poşetlerin ücretsiz olduğu anlamına gelmez.","url":"https://www4.skatteverket.se/rattsligvagledning/edition/2024.7/378022.html","source":"İsveç Vergi İdaresi","type":"Kaldırılmış çevre vergisi"},{"id":"ee-car","country":"EE","title":"Araba İçin Yıllık ve Kayıt Vergisi","period":"2025–günümüz","year":2025,"status":"aktif","group":"Ulaşım","motifs":["araç","kayıt","karbon","sahiplik"],"teaser":"Arabanın yaşı, ağırlığı ve CO₂'si hesapta.","story":"Estonya'da 1 Ocak 2025'ten itibaren kayıtlı motorlu araçların yıllık vergisi ve ilk tescil/kapsama giren bazı mülkiyet değişikliklerinde kayıt ücreti vardır. Hesapta CO₂, ağırlık ve aracın yaşı gibi değişkenler bulunabilir.","url":"https://www.emta.ee/en/private-client/taxes-and-payment/other-taxes/motor-vehicle-tax/tax-rates-and-calculation-tax","source":"Estonya Vergi ve Gümrük Kurumu","type":"Araç vergisi"},{"id":"mt-eco","country":"MT","title":"Turistin Gecelik Eko Katkısı","period":"2016–günümüz","year":2016,"status":"aktif","group":"Çevre","motifs":["geceleme","turizm","çevre","harç"],"teaser":"Malta'da oteldeki her gece için çevre payı.","story":"Malta'da 2016'dan beri konaklamada eko katkı payı alınır. 1 Temmuz 2026'dan itibaren 18 yaş üstü ziyaretçiler için kişi başı gecelik 1,50 €, toplamda 22,50 € tavan geçerli. Bu ücret konaklama türlerine göre ilgili düzenleme kapsamında alınır.","url":"https://mtca.gov.mt/business-tax/eco/eco-on-accommodation","source":"Malta Vergi ve Gümrük İdaresi","type":"Konaklama katkısı"},{"id":"sk-transfer","country":"SK","title":"Banka Havalesi İşlem Vergisi","period":"2025–günümüz","year":2025,"status":"aktif","group":"Teknoloji","motifs":["banka","transfer","işletme","ödeme"],"teaser":"Şirketin hesabından çıkan para ayrıca vergili.","story":"Slovakya 2025'te şirket ve başlangıçta bazı girişimciler için finansal işlem vergisini uygulamaya koydu. 2026 itibarıyla gerçek kişi girişimciler kapsam dışında; kapsam içindeki şirketlerin bazı hesap çıkış işlemlerinde %0,4 (işlem başına en çok 40 €) kuralı geçerli. Her bireysel havaleye uygulanan vergi değil.","url":"https://www.financnasprava.sk/sk/aktualne-dan-clo/faq/dan-financne-transakcie","source":"Slovakya Mali İdaresi","type":"Finansal işlem vergisi"},{"id":"vn-plastic","country":"VN","title":"Kilogramla Poşet Çevre Vergisi","period":"2012–günümüz","year":2012,"status":"aktif","group":"Çevre","motifs":["poşet","plastik","üretim","atık"],"teaser":"Poşetin adedi değil kilosu vergi hesabına giriyor.","story":"Vietnam'ın çevre koruma vergisi belirli çevreye zararlı malların üretim veya ithalatında tahsil edilir. Vergi kapsamındaki plastik poşetler, sıradan market poşetlerini tek tek alan tüketici yerine kilogram esaslı bir vergi sınıfıdır. Mevzuatta muaf tutulan ambalajlar vardır; oranlar dönemsel değişebilir.","url":"https://fia.mof.gov.vn/en/Single/MenuID/793a43ff-0059-4504-b747-934193322015","source":"Vietnam Maliye Bakanlığı","type":"Çevre koruma vergisi"},{"id":"sa-energy","country":"SA","title":"Enerji İçeceğine %100 Özel Vergi","period":"2017–günümüz","year":2017,"status":"aktif","group":"Yiyecek","motifs":["enerji","içecek","şeker","sağlık"],"teaser":"Enerji içeceğinin özel tüketim vergisi %100.","story":"Suudi Arabistan'da enerji içecekleri için seçici tüketim vergisi 2017'den beri %100 düzeyinde uygulanıyor. Tatlandırılmış diğer içeceklerin 2026 itibarıyla farklı, şeker miktarına dayanan kademeli modele geçmesi enerji içeceklerinin oranını değiştirmiyor.","url":"https://zatca.gov.sa/en/RulesRegulations/Taxes/Pages/excise-tax.aspx","source":"Suudi Vergi ve Gümrük Kurumu (ZATCA)","type":"Özel tüketim vergisi"},{"id":"ae-sugar","country":"AE","title":"İçecekte Şeker Gramına Göre Vergi","period":"2026–günümüz","year":2026,"status":"aktif","group":"Yiyecek","motifs":["şeker","enerji","içecek","sağlık"],"teaser":"Şeker gramı yükseldikçe litre başına vergi değişiyor.","story":"Birleşik Arap Emirlikleri 2026'da şekerli içecekler için sabit yüzdelik vergi yerine 100 mL'deki şeker içeriğine bağlı kademeli hacim modeli getirdi. Az şekerli ürünlerde vergi sıfıra inebilir; enerji içeceklerinde %100 özel vergi farklı hesaplanır.","url":"https://tax.gov.ae/en/eparticipation/fta.blogs/1444.aspx","source":"BAE Federal Vergi Otoritesi, 2026","type":"Kademeli tüketim vergisi"},{"id":"ae-energy","country":"AE","title":"Enerji İçeceğine %100 Vergi","period":"2017–günümüz","year":2017,"status":"aktif","group":"Yiyecek","motifs":["enerji","içecek","sağlık","şeker"],"teaser":"Bir kutu enerji içeceğinin vergi oranı %100.","story":"Birleşik Arap Emirlikleri'nde enerji içecekleri özel tüketim vergisi kapsamında %100 oranıyla vergilendiriliyor. 2026'da diğer şekerli içeceklere getirilen şeker içerik modeli enerji içeceklerine uygulanmıyor.","url":"https://www.tax.gov.ae/en/taxes/excise.tax/excise.tax.topics/calculating.excise.tax.according.aspx","source":"BAE Federal Vergi Otoritesi","type":"Özel tüketim vergisi"},{"id":"fi-soft","country":"FI","title":"Bitkisel Sütteki Şekere Kadar İçecek Vergisi","period":"Güncel","year":2026,"status":"aktif","group":"Yiyecek","motifs":["şeker","içecek","bitkisel","süt"],"teaser":"Aromalı yulaf içeceği bile vergi listesine girebilir.","story":"Finlandiya'da meşrubat özel tüketim vergisi yalnızca gazozla sınırlı değildir; bazı tatlandırılmış yulaf veya soya gibi bitkisel süt alternatifleri de ürün kodu ve şeker içeriğine göre kapsam dahilinde olabilir. Belirli sade, besleyici ürünlerde istisna vardır.","url":"https://www.vero.fi/en/businesses-and-corporations/taxes-and-charges/excise-taxation/excise-duty-on-soft-drinks/","source":"Finlandiya Vergi İdaresi","type":"İçecek özel tüketim vergisi"},{"id":"kz-google","country":"KZ","title":"Google Vergisi / Yabancı Platform KDV'si","period":"2022–günümüz","year":2022,"status":"aktif","group":"Teknoloji","motifs":["internet","dijital","platform","abonelik"],"teaser":"Yurt dışındaki dijital platformlar da ülkeye vergi ödüyor.","story":"Kazakistan'da 2022'de başlayan uygulamada ülke içindeki tüketicilere dijital hizmet veya çevrimiçi mal sağlayan yabancı platformlara özel KDV kayıt ve beyan yükümlülüğü getirildi. 2025'te devlet, kayıtlı platformlar arasında OpenAI ve çeşitli oyun/hizmet şirketlerini de saydı. Bu bir kullanıcı başına özel 'Google harcı' değil, KDV mekanizmasıdır.","url":"https://www.gov.kz/org/kgd/press/news/details/1099769?lang=en","source":"Kazakistan Devlet Gelirleri Komitesi","type":"Dijital KDV"},{"id":"pl-sugar","country":"PL","title":"Şeker ve Kafeinli İçecek Harcı","period":"2021–günümüz","year":2021,"status":"aktif","group":"Yiyecek","motifs":["şeker","kafein","enerji","içecek"],"teaser":"İçecekte hem şeker hem kafein mi var? İki kalem var.","story":"Polonya 2021'de şekerli veya tatlandırıcılı içeceklere özel bir ücret getirdi. Şeker miktarı arttıkça ücret artarken kafein ya da taurin eklenen ürünlerde ilave bileşen bulunur; üretici veya ilk piyasaya arz eden taraf yükümlüdür.","url":"https://www.gov.pl/web/ijhars/podatek-cukrowy","source":"Polonya Kamu Gıda Denetimi","type":"Ürün harcı"},{"id":"at-dog","country":"AT","title":"Viyana Köpek Vergisi","period":"Güncel","year":2026,"status":"aktif","group":"Hayvan","motifs":["köpek","evcil","belediye","kayıt"],"teaser":"Köpek sayısı arttıkça belediye vergisi de artıyor.","story":"Avusturya'nın Viyana kentinde 2026 itibarıyla ilk köpek için yıllık 72 €, her ek köpek için 105 € belediye vergisi tahsil ediliyor. 1 Ocak 2027 için farklı tarife ilan edilmiştir. Bu Viyana'ya özgü yerel vergi olup bütün ülkeye aynı tutar uygulanmaz.","url":"https://www.wien.gv.at/amtswege/hundeabgabe-hundesteuer-meldung","source":"Viyana Belediyesi","type":"Belediye köpek vergisi"},{"id":"es-plastic","country":"ES","title":"Geri Dönüşmemiş Plastiğin Kilosuna Vergi","period":"2023–günümüz","year":2023,"status":"aktif","group":"Çevre","motifs":["plastik","ambalaj","üretim","atık"],"teaser":"Ambalajda kaç kilo geri dönüşmemiş plastik var?","story":"İspanya'da 1 Ocak 2023'te yürürlüğe giren vergi, tekrar kullanılmayan plastik içeren ambalajların içindeki geri dönüştürülmemiş plastik kilosuna göre hesaplanır. Resmî oran 0,45 €/kg; üretim ve ithalat gibi belirli işlemlere uygulanır.","url":"https://sede.agenciatributaria.gob.es/Sede/impuestos-especiales-medioambientales/impuesto-especial-sobre-envases-plastico-reutilizables/base-imponible-tipo-impositivo-cuota-tributaria.html","source":"İspanya Vergi Ajansı","type":"Çevre vergisi"},{"id":"pt-sugar","country":"PT","title":"İçecekte Şeker Basamağı Vergisi","period":"2017–günümüz","year":2017,"status":"aktif","group":"Yiyecek","motifs":["şeker","sağlık","içecek","davranış"],"teaser":"Şekeri azaltan içecek üreticisi daha düşük vergiyle karşılaşabilir.","story":"Portekiz 2017'de ilave şeker ve tatlandırıcı içeren belirli içecekler için özel tüketim vergisi getirdi. Vergi düzeyleri şeker oranına göre farklılaştırıldı ve ilk yılda ürünlerin yeniden formüle edildiği resmî değerlendirmelere yansıdı.","url":"https://portugal.gov.pt/gc21/comunicacao/noticias/acucar-ingerido-pelos-portugueses-em-bebidas-diminuiu-6-250-toneladas","source":"Portekiz Hükûmeti","type":"İçecek özel tüketim vergisi"},{"id":"my-ttx","country":"MY","title":"Yabancı Turiste Oda Başına Gece Vergisi","period":"2017–günümüz","year":2017,"status":"aktif","group":"Seyahat","motifs":["turizm","otel","geceleme","harç"],"teaser":"Otel odasını kaç gece tuttun? Her gece ayrı ücret.","story":"Malezya'nın Tourism Tax düzenlemesinde kapsamdaki yabancı ziyaretçiler için otellerde oda başına gecelik 10 ringgit tutarı bulunur. İlgili tahsilat ve muafiyetler otel veya rezervasyon platformunun statüsüne göre değişebilir; tüm Malezya vatandaşlarına uygulanan bir oda vergisi değildir.","url":"https://www.myttx.customs.gov.my/","source":"Malezya Kraliyet Gümrük İdaresi","type":"Konaklama vergisi"},{"id":"ke-housing","country":"KE","title":"Maaştan Kesilen Konut Katkı Payı","period":"2024–günümüz","year":2024,"status":"aktif","group":"Ev","motifs":["konut","maaş","işveren","çalışma"],"teaser":"Maaştan %1,5, işverenden bir %1,5 daha.","story":"Kenya'da 2024 Uygun Fiyatlı Konut Yasası uyarınca çalışanların brüt maaşının %1,5'i, işverenlerinden de eşit tutarda Affordable Housing Levy toplanır. Kapsama giren diğer gelirlerde ayrıca kurallar vardır. Amaç konut finansmanıdır.","url":"https://www.kra.go.ke/news-center/public-notices/2099-collection-of-the-affordable-housing-levy-by-kenya-revenue-authority-2","source":"Kenya Revenue Authority","type":"Konut katılım payı"},{"id":"gh-etransfer","country":"GH","title":"Mobil Para Transferi E-Levy","period":"2022–2025","year":2022,"status":"gecmis","group":"Teknoloji","motifs":["banka","transfer","internet","ödeme"],"teaser":"Para göndermek de bir dönem vergilendirildi.","story":"Gana'da mobil para ve kapsam içindeki elektronik transferlere E-Levy uygulanıyordu. 2022'de başlayan sistemde son dönemde oran %1 idi. 2 Nisan 2025'te kanunen kaldırıldı; resmî sitede eski SSS hâlâ görülebilse de artık yürürlükte değil.","url":"https://presidency.gov.gh/promises-fulfilled-e-levy-and-other-taxes-officially-scrapped/","source":"Gana Cumhurbaşkanlığı, 2 Nisan 2025","type":"Kaldırılmış transfer harcı"},{"id":"gh-emission","country":"GH","title":"Araç Emisyon Vergisi","period":"2024–2025","year":2024,"status":"gecmis","group":"Çevre","motifs":["araç","emisyon","karbon","iklim"],"teaser":"Egzoz emisyonunu vergilendiren yasa kısa sürdü.","story":"Gana'nın Emissions Levy Act 2023 düzenlemesi 2024'te uygulamaya girdi. 2 Nisan 2025'te E-Levy ile birlikte kaldırılan vergiler arasındaydı. Güncel araç emisyon vergisi gibi gösterilmemelidir.","url":"https://presidency.gov.gh/promises-fulfilled-e-levy-and-other-taxes-officially-scrapped/","source":"Gana Cumhurbaşkanlığı, 2025","type":"Kaldırılmış emisyon vergisi"},{"id":"pe-bag","country":"PE","title":"Poşet Satın Alınca Adet Başına Vergi","period":"2019–günümüz","year":2019,"status":"aktif","group":"Çevre","motifs":["poşet","plastik","alışveriş","atık"],"teaser":"Peru'da alışveriş poşeti vergi birimi.","story":"Peru'nun plastik poşet tüketim vergisi 1 Ağustos 2019'dan itibaren uygun kapsamda verilen alışveriş poşeti başına hesaplanır. Başlangıçta 0,10 sol olan tutar her yıl arttı ve 2023'ten itibaren poşet başına 0,50 sol düzeyine yükseldi.","url":"https://orientacion.sunat.gob.pe/7282-03-monto","source":"Peru SUNAT","type":"Plastik tüketim vergisi"},{"id":"cr-lux","country":"CR","title":"Lüks Ev Dayanışma Vergisi","period":"2009–günümüz","year":2009,"status":"aktif","group":"Ev","motifs":["konut","lüks","servet","emlak"],"teaser":"Çok pahalı evin ayrı dayanışma vergisi.","story":"Kosta Rika'da konutun inşaat ve kalıcı tesis değerinin belirli eşiği aşması durumunda dayanışma vergisi doğabilir. 2026 için resmî bildirilen eşik 143 milyon kolon; gelir konut programlarına ayrılır. Bütün evler için ek vergi değildir.","url":"https://www.hacienda.go.cr/","source":"Kosta Rika Maliye Bakanlığı (2026)","type":"Değerli konut vergisi"},{"id":"is-lodging","country":"IS","title":"Kamp Alanına ve Karavana Gece Vergisi","period":"2024–günümüz","year":2024,"status":"aktif","group":"Seyahat","motifs":["kamp","karavan","geceleme","turizm"],"teaser":"Otelde de kamp alanında da gecelik vergi var.","story":"İzlanda'da konaklama vergisi otel odaları kadar kamp ve karavan parklarını da kapsar. 2025'ten itibaren oteller gibi tesisler için birim başına 800 ISK; kamp ve karavan parkı için 400 ISK uygulanır. Ücret kişi başına değil düzenlenen konaklama birimi esasına göre hesaplanır.","url":"https://www.skatturinn.is/english/companies/tax-issues/lodging-tax","source":"İzlanda Vergi İdaresi","type":"Konaklama vergisi"},{"id":"no-sugar","country":"NO","title":"Toz Şekerin Kilosuna Özel Vergi","period":"Güncel","year":2026,"status":"aktif","group":"Yiyecek","motifs":["şeker","üretim","ham madde","ithalat"],"teaser":"Şeker kristali kilosuyla vergilendiriliyor.","story":"Norveç'te toz şeker, küp şeker ve bazı şeker çözeltilerinin üretimi veya ithalatı için özel vergi uygulanır. 2026 oranı kilogram başına 9,76 NOK. Gıdanın içinde bileşen olarak kullanılan şekerin bazı kullanımlarında muafiyet vardır.","url":"https://www.skatteetaten.no/en/business-and-organisation/vat-and-duties/excise-duties/about-the-excise-duties/sugar/","source":"Norveç Vergi İdaresi","type":"Şeker tüketim vergisi"},{"id":"gr-climate","country":"GR","title":"Otelde İklim Krizi Dayanıklılık Harcı","period":"2024–günümüz","year":2024,"status":"aktif","group":"Seyahat","motifs":["konaklama","iklim","turizm","geceleme"],"teaser":"Otel odası için gecelik iklim krizi makbuzu.","story":"Yunanistan, turistik konaklamalarda oda veya daire başına bir iklim krizi dayanıklılık harcı uygular. Mevsim ve konaklama sınıfına göre değişen tutarlar işletme tarafından aylık beyan edilir. Herkese sabit tek fiyatlı bir giriş vergisi değildir.","url":"https://aade.gr/en/climate-crisis-resilience-fee-issuance-statement","source":"Yunanistan Bağımsız Kamu Gelirleri Kurumu","type":"İklim dayanıklılık harcı"},{"id":"lk-social","country":"LK","title":"Sosyal Güvenlik Katkı Vergisi","period":"2022–günümüz","year":2022,"status":"aktif","group":"Toplum","motifs":["işletme","ciro","ithalat","katılım"],"teaser":"Kâr değil belirli işlemlerde ciro esas alınıyor.","story":"Sri Lanka'da Social Security Contribution Levy 1 Ekim 2022'de başladı. Kanuni oran %2,5 olup ithalat, üretim, hizmet ve ticarette yükümlü işletmenin kapsama giren ciro hesabı farklılaştırılır. Verginin adı bireysel sigorta primi izlenimi verse de her ücretlinin maaşından alınan ayrı prim değildir.","url":"https://www.ird.gov.lk/en/Type%20of%20Taxes/SitePages/Social%20Security%20Contribution%20Levy%20%28SSCL%29.aspx","source":"Sri Lanka Inland Revenue Department","type":"Ciro esaslı katkı vergisi"},{"id":"dk-candy","country":"DK","title":"Çikolata, Marzipan ve Sakız Vergisi","period":"Güncel","year":2026,"status":"aktif","group":"Yiyecek","motifs":["şeker","çikolata","sakız","marzipan"],"teaser":"Sakız bile tatlı mamul vergisi kategorisinde.","story":"Danimarka'nın çikolata ve şekerleme özel tüketim vergisi, çikolatayla sınırlı değil. Marzipan, nugat, şekerleme, sakız ve bazı kakaolu ürünler kapsama giriyor. Üretici ve ithalatçı açısından kayıt ve beyan yükümlülüğü doğurabilir.","url":"https://skat.dk/erhverv/afgifter-paa-varer-og-ydelser-punktafgifter/afgifter-paa-chokolade-sukkervarer-og-konsum-is","source":"Danimarka Vergi İdaresi","type":"Şekerleme özel tüketim vergisi"},{"id":"de-coffee","country":"DE","title":"Kahvenin Kilosuna Federal Vergi","period":"Güncel","year":2026,"status":"aktif","group":"Gündelik","motifs":["kahve","kafein","ithalat","üretim"],"teaser":"Sade kahve bile ayrı federal tüketim vergisine tabi.","story":"Almanya'da kavrulmuş kahve ve çözünebilir kahve için federal kahve vergisi bulunur. Kahve genel KDV'den ayrı bir özel tüketim vergisi kategorisidir; 2024 resmî gümrük istatistiklerinde milyar avro ölçeğinde tahsilat gösterilir.","url":"https://www.zoll.de/EN/Businesses/Movement-of-goods/Import/Duties-and-taxes/Excise-duties/excise-duties_node.html","source":"Almanya Gümrük İdaresi","type":"Kahve vergisi"},{"id":"ie-empty","country":"IE","title":"Boş Tutulan Ev Vergisi","period":"2023–günümüz","year":2023,"status":"aktif","group":"Ev","motifs":["konut","boş ev","kira","emlak"],"teaser":"Yılın çoğunda boş duran mesken vergilendiriliyor.","story":"İrlanda'da 12 aylık değerlendirme döneminde konut olarak 30 günden az kullanılan kapsamdaki taşınmazlar Vacant Homes Tax değerlendirmesine tabidir. Amaç boş mülkleri kiralama veya satış için piyasaya çekmektir; muafiyetler vardır.","url":"https://www.revenue.ie/en/property/vacant-homes-tax/apply/index.aspx","source":"İrlanda Revenue, 2026","type":"Boş konut vergisi"},{"id":"ie-sugar","country":"IE","title":"Şekerli İçeceğin 100 mL Hesabı","period":"2018–günümüz","year":2018,"status":"aktif","group":"Yiyecek","motifs":["şeker","içecek","sağlık","davranış"],"teaser":"100 mL'de 5 gram şeker eşiğini aşınca vergi.","story":"İrlanda'nın şekerli içecek tüketim vergisi 1 Mayıs 2018'de başladı. Belirli şeker eklenmiş içeceklerin ilk arzında 100 mL başına en az 5 gram toplam şeker koşulu uygulanır ve daha yüksek şekerde farklı oran kullanılır.","url":"https://www.revenue.ie/en/companies-and-charities/excise-and-licences/sugar-sweetened-drinks-tax/index.aspx","source":"İrlanda Revenue","type":"İçecek tüketim vergisi"},{"id":"za-tyres","country":"ZA","title":"Otomobil Lastiği Çevre Vergisi","period":"Güncel","year":2026,"status":"aktif","group":"Çevre","motifs":["lastik","araç","atık","geri dönüşüm"],"teaser":"Araba lastiğinin atığı için üretici vergisi.","story":"Güney Afrika'da yeni, kullanılmış veya kaplanmış bazı pnömatik lastiklerin üretimi çevre harcına tabidir. Vergi lastiği satın alan bireyin ayrı beyan ettiği bir işlem değil; üretici ve kapsama giren sorumluların hesabıdır.","url":"https://www.sars.gov.za/customs-and-excise/excise/environmental-levy-products/tyres/","source":"Güney Afrika Gelir İdaresi","type":"Üretici çevre harcı"}];
